#[ignore]
async fn e2e_p1_concurrent_user_creation_with_cancellation() {
    // RED PHASE: Concurrent creation with cancellation safety
    // EXPECTED: Multiple concurrent calls work, cancellation doesn't corrupt state

    let mut handles = vec![];

    // Spawn multiple user creations concurrently
    for i in 0..5 {
        let name = format!("User{}", i);
        let handle = tokio::spawn(async move {
            create_user(name).await
        });
        handles.push(handle);
    }

    // Wait for all to complete
    for handle in handles {
        let result = handle.await;
        assert!(result.is_ok(), "Task should complete");
        let creation = result.unwrap();
        assert!(creation.is_ok(), "User creation should succeed");
    }
}

