#[tokio::test]
#[ignore]
async fn e2e_p1_partial_progress_cleanup_on_cancel() {
    // RED PHASE: Cleanup behavior on cancellation
    // EXPECTED: No resource leaks when future is dropped

    let success_count = Arc::new(AtomicUsize::new(0));
    let counter = success_count.clone();

    // Scenario: Create users but cancel mid-sequence
    let future = async {
        for i in 0..10 {
            let name = format!("User{}", i);
            if let Ok(_) = create_user(name).await {
                counter.fetch_add(1, Ordering::SeqCst);
